def fit(fn,p0):
    best=None
    for s in range(20):
        p=np.random.RandomState(s).randn(len(p0))*np.array(p0)+np.array(p0)*0 if s else np.array(p0,float)
        try:
            r=least_squares(lambda q: fn(q)-dP_dt, p)
        except Exception as e: continue
        if best is None or r.cost<best.cost: best=r
